import { z } from "zod";
import { Beat } from "./providers";

/**
 * Zod schema for individual beat elements in LLM responses.
 * Permissive to accommodate minor key variations from open-source models.
 */
export const RawBeatSchema = z.object({
  id: z.string().optional(),
  title: z.string().optional(),
  storyExcerpt: z.string().optional(),
  narrativeContext: z.string().optional(),
  imagePrompt: z.string().optional(),
  // Alternate aliases occasionally generated by models:
  sceneTitle: z.string().optional(),
  headline: z.string().optional(),
  excerpt: z.string().optional(),
  quote: z.string().optional(),
  context: z.string().optional(),
  reason: z.string().optional(),
  prompt: z.string().optional(),
  visualPrompt: z.string().optional(),
});

export const RawBeatsPayloadSchema = z.union([
  z.object({
    beats: z.array(RawBeatSchema).min(1, "LLM returned empty beats array"),
  }),
  z.object({
    storyBeats: z.array(RawBeatSchema).min(1, "LLM returned empty beats array"),
  }),
  z.object({
    scenes: z.array(RawBeatSchema).min(1, "LLM returned empty beats array"),
  }),
  z.array(RawBeatSchema).min(1, "LLM returned empty beats array"),
]);

/**
 * Robustly extracts and sanitizes JSON string from LLM completion text,
 * stripping markdown code fences or conversational conversational preambles.
 */
export function extractJsonFromText(rawText: string): string {
  let cleaned = rawText.trim();

  // 1. Try markdown code block regex ```(?:json)? ... ```
  const codeBlockRegex = /```(?:json)?\s*([\s\S]*?)\s*```/i;
  const match = cleaned.match(codeBlockRegex);
  if (match && match[1]) {
    cleaned = match[1].trim();
  }

  // 2. If it doesn't start with { or [, locate the first occurrence
  const firstBrace = cleaned.indexOf("{");
  const firstBracket = cleaned.indexOf("[");

  let startIndex = -1;
  if (firstBrace !== -1 && firstBracket !== -1) {
    startIndex = Math.min(firstBrace, firstBracket);
  } else if (firstBrace !== -1) {
    startIndex = firstBrace;
  } else if (firstBracket !== -1) {
    startIndex = firstBracket;
  }

  if (startIndex > -1) {
    // Find matching last closing character
    const isObject = cleaned[startIndex] === "{";
    const closingChar = isObject ? "}" : "]";
    const lastIndex = cleaned.lastIndexOf(closingChar);
    if (lastIndex > startIndex) {
      cleaned = cleaned.substring(startIndex, lastIndex + 1);
    }
  }

  return cleaned;
}

/**
 * Attempts to parse JSON string with fallbacks for common syntax hiccups (trailing commas).
 */
export function safeJsonParse(jsonString: string): any {
  try {
    return JSON.parse(jsonString);
  } catch (initialError) {
    // Attempt removing trailing commas before closing braces/brackets
    const sanitized = jsonString
      .replace(/,\s*([}\]])/g, "$1")
      // Remove any trailing unescaped control chars if present
      .replace(/[\u0000-\u001F]+/g, (match) => {
        // preserve newlines, carriage returns, tabs in string literals
        if (match === "\n" || match === "\r" || match === "\t") return match;
        return "";
      });

    try {
      return JSON.parse(sanitized);
    } catch (secondError) {
      throw new Error(
        `Failed to parse LLM output as JSON: ${(initialError as Error).message}. Raw content preview: "${jsonString.slice(
          0,
          200
        )}..."`
      );
    }
  }
}

/**
 * Sanitizes and validates the extracted raw data into a strictly typed Beat array.
 */
export function parseAndValidateBeats(rawContent: string): Beat[] {
  const extracted = extractJsonFromText(rawContent);
  const parsed = safeJsonParse(extracted);

  const validationResult = RawBeatsPayloadSchema.safeParse(parsed);
  if (!validationResult.success) {
    throw new Error(
      `Invalid beat schema: ${validationResult.error.issues
        .map((i) => `${i.path.join(".")}: ${i.message}`)
        .join(", ")}`
    );
  }

  const data = validationResult.data;
  let rawBeats: z.infer<typeof RawBeatSchema>[] = [];
  if (Array.isArray(data)) {
    rawBeats = data;
  } else if ("beats" in data && Array.isArray(data.beats)) {
    rawBeats = data.beats;
  } else if ("storyBeats" in data && Array.isArray(data.storyBeats)) {
    rawBeats = data.storyBeats;
  } else if ("scenes" in data && Array.isArray(data.scenes)) {
    rawBeats = data.scenes;
  }

  return rawBeats.map((beat, index) => {
    const id = beat.id || `beat-${index + 1}`;
    const title =
      beat.title ||
      beat.sceneTitle ||
      beat.headline ||
      `Scene Beat ${index + 1}`;
    const storyExcerpt =
      beat.storyExcerpt ||
      beat.excerpt ||
      beat.quote ||
      "";
    const narrativeContext =
      beat.narrativeContext ||
      beat.context ||
      beat.reason ||
      "";
    const imagePrompt =
      beat.imagePrompt ||
      beat.prompt ||
      beat.visualPrompt ||
      `${title}. ${storyExcerpt}`;

    return {
      id,
      title: title.trim(),
      storyExcerpt: storyExcerpt.trim(),
      narrativeContext: narrativeContext.trim(),
      imagePrompt: imagePrompt.trim(),
      status: "pending" as const,
    };
  });
}
